"""Rust emitter: the colours native code draws with, and nothing else.

Today that is the tray icon's dot (src-tauri/src/tray.rs), which is painted onto
the app's PNG at start-up from `signal`. The webview never needs these; it has
`tokens.css`.
"""

from .contrast import parse_rgba
from .model import Tokens

HEADER = """\
// Generated by scripts/generate-tokens.py from design/tokens.toml.
// Do not edit — edit the source and regenerate. CI fails on drift.
"""


def _rgba(value: str) -> str:
    if value.startswith("rgb"):
        r, g, b, alpha = parse_rgba(value)
        a = round(alpha * 255)
    else:
        h = value.lstrip("#")
        r, g, b = (int(h[i : i + 2], 16) for i in (0, 2, 4))
        a = 255
    return f"[0x{r:02X}, 0x{g:02X}, 0x{b:02X}, 0x{a:02X}]"


def emit_rust(tokens: Tokens) -> str:
    out = [HEADER]
    for appearance in ("light", "dark"):
        colour = tokens.appearances[appearance].colors["signal"]
        out.append(
            f"\n/// `signal` in the {appearance} appearance, as RGBA.\n"
            "#[allow(dead_code)]\n"
            f"pub const SIGNAL_{appearance.upper()}_RGBA: [u8; 4] = {_rgba(colour)};\n"
        )
    return "".join(out)
